pub struct BatchReplicationConfig {
    pub max_batch_size: usize,      // 32 entries per batch
    pub flush_interval_ms: u64,     // Flush every 10ms
    pub max_pending_batches: usize, // 3 batches in flight
}

impl Default for BatchReplicationConfig {
    fn default() -> Self {
        Self {
            max_batch_size: 32,
            flush_interval_ms: 10,
            max_pending_batches: 3,
        }
    }
}

// Batch buffer for each follower
pub struct FollowerBatchBuffer {
    follower_id: u32,
    entries: Vec<LogEntry>,
    last_flush: u64,
    config: BatchReplicationConfig,
}

impl FollowerBatchBuffer {
    pub fn new(follower_id: u32, config: BatchReplicationConfig) -> Self {
        Self {
            follower_id,
            entries: Vec::with_capacity(config.max_batch_size),
            last_flush: 0,
            config,
        }
    }

    // Add entry to batch, flush if full
    pub fn add_entry(&mut self, entry: LogEntry, current_time: u64) -> bool {
        self.entries.push(entry);

        // Check if batch should flush
        if self.entries.len() >= self.config.max_batch_size {
            return true;  // Signal flush needed
        }

        // Check time-based flush
        if current_time - self.last_flush > self.config.flush_interval_ms {
            return true;
        }

        false
    }

    // Get and clear batch
    pub fn flush(&mut self, current_time: u64) -> Vec<LogEntry> {
        let batch = std::mem::take(&mut self.entries);
        self.last_flush = current_time;
        batch
    }

    pub fn is_empty(&self) -> bool {
        self.entries.is_empty()
    }

    pub fn len(&self) -> usize {
        self.entries.len()
    }
}

// Leader's batch replication manager
pub struct BatchReplicator {
    followers: std::collections::HashMap<u32, FollowerBatchBuffer>,
    config: BatchReplicationConfig,
    stats: BatchStats,
}

pub struct BatchStats {
    pub total_batches_sent: u64,
    pub total_entries_sent: u64,
    pub avg_batch_size: f64,
    pub latency_p99_ms: u64,
}

impl BatchReplicator {
    pub fn new(config: BatchReplicationConfig) -> Self {
        Self {
            followers: std::collections::HashMap::new(),
            config,
            stats: BatchStats {
                total_batches_sent: 0,
                total_entries_sent: 0,
                avg_batch_size: 0.0,
                latency_p99_ms: 0,
            },
        }
    }

    pub fn register_follower(&mut self, follower_id: u32) {
        self.followers.insert(
            follower_id,
            FollowerBatchBuffer::new(follower_id, self.config.clone()),
        );
    }

    // Optimized: Single entry → batch
    pub fn queue_entry_for_replication(
        &mut self,
        follower_id: u32,
        entry: LogEntry,
        current_time: u64,
    ) -> Vec<(u32, Vec<LogEntry>)> {
        let mut flushes = Vec::new();

        if let Some(buffer) = self.followers.get_mut(&follower_id) {
            if buffer.add_entry(entry, current_time) {
                if let Some(batch) = self.followers.remove(&follower_id) {
                    let flushed = batch.flush(current_time);
                    if !flushed.is_empty() {
                        flushes.push((follower_id, flushed));
                    }
                    self.followers.insert(follower_id, batch);
                }
            }
        }

        flushes
    }

    // Batch flush (timer-based)
    pub fn flush_pending(&mut self, current_time: u64) -> Vec<(u32, Vec<LogEntry>)> {
        let mut flushes = Vec::new();

        for (follower_id, buffer) in self.followers.iter_mut() {
            if !buffer.is_empty() {
                let batch = buffer.flush(current_time);
                if !batch.is_empty() {
                    self.stats.total_batches_sent += 1;
                    self.stats.total_entries_sent += batch.len() as u64;

                    flushes.push((*follower_id, batch));
                }
            }
        }

        // Update average batch size
        if self.stats.total_batches_sent > 0 {
            self.stats.avg_batch_size =
                self.stats.total_entries_sent as f64 / self.stats.total_batches_sent as f64;
        }

        flushes
    }

    pub fn stats(&self) -> &BatchStats {
        &self.stats
    }
}

// Optimized conflict resolution (instead of linear backtrack)
pub fn find_conflict_point(
    log: &[LogEntry],
    conflict_term: u64,
    mut conflict_index: usize,
) -> usize {
    // Binary search instead of linear scan
    let mut left = 0;
    let mut right = conflict_index;

    while left < right {
        let mid = (left + right) / 2;
        if log[mid].term < conflict_term {
            left = mid + 1;
        } else {
            right = mid;
        }
    }

    left
}

// Optimized quorum check (O(n) instead of O(n²))
pub fn advance_commit_index_batched(
    leader: &mut RaftNode,
    cluster: &[u32],
) {
    let quorum_size = (cluster.len() / 2) + 1;
    let mut replica_counts: std::collections::HashMap<usize, usize> = std::collections::HashMap::new();

    // Count replicas per index once
    for follower_id in cluster.iter() {
        if *follower_id != leader.id {
            if let Some(&match_index) = leader.match_index.get(follower_id) {
                for idx in 0..=match_index {
                    *replica_counts.entry(idx).or_insert(0) += 1;
                }
            }
        }
    }

    // Add leader replica count
    for idx in 0..leader.log.len() {
        *replica_counts.entry(idx).or_insert(0) += 1;
    }

    // Find highest index with quorum
    for idx in (leader.commit_index + 1)..leader.log.len() {
        if let Some(&count) = replica_counts.get(&idx) {
            if count >= quorum_size {
                leader.commit_index = idx;
            }
        }
    }
}

