use std::collections::VecDeque;
use std::sync::atomic::{AtomicUsize, Ordering};
use std::sync::Arc;

// Fixed-size ring buffer for wakeup events (1024 slots)
pub struct WakeupRing {
    ring: Vec<WakeupEvent>,
    head: AtomicUsize,
    tail: AtomicUsize,
    mask: usize,  // Capacity - 1 (for modulo via bitwise AND)
}

impl WakeupRing {
    pub fn new() -> Self {
        let capacity = 1024;  // Power of 2
        Self {
            ring: vec![WakeupEvent::default(); capacity],
            head: AtomicUsize::new(0),
            tail: AtomicUsize::new(0),
            mask: capacity - 1,
        }
    }

    // O(1) push with overflow handling
    pub fn push(&self, event: WakeupEvent) -> bool {
        let tail = self.tail.load(Ordering::Relaxed);
        let next_tail = (tail + 1) & self.mask;
        let head = self.head.load(Ordering::Acquire);

        if next_tail == head {
            // Ring full - discard oldest event
            self.head.store((head + 1) & self.mask, Ordering::Release);
        }

        // SAFETY: Index is always valid due to mask
        unsafe {
            *self.ring.get_unchecked_mut(tail) = event;
        }
        self.tail.store(next_tail, Ordering::Release);
        true
    }

    // O(1) pop
    pub fn pop(&self) -> Option<WakeupEvent> {
        let head = self.head.load(Ordering::Relaxed);
        let tail = self.tail.load(Ordering::Acquire);

        if head == tail {
            return None;  // Empty
        }

        let event = unsafe {
            *self.ring.get_unchecked(head)
        };

        self.head.store((head + 1) & self.mask, Ordering::Release);
        Some(event)
    }

    pub fn len(&self) -> usize {
        let head = self.head.load(Ordering::Relaxed);
        let tail = self.tail.load(Ordering::Relaxed);
        (tail - head) & self.mask
    }
}

// VecDeque-based ready queue (O(1) operations at both ends)
pub struct OptimizedTaskQueue {
    ready_queue: VecDeque<u32>,
    suspended_map: std::collections::HashSet<u32>,
}

impl OptimizedTaskQueue {
    pub fn new() -> Self {
        Self {
            ready_queue: VecDeque::with_capacity(1000),
            suspended_map: std::collections::HashSet::new(),
        }
    }

    // O(1) pop from front
    pub fn dequeue_ready(&mut self) -> Option<u32> {
        self.ready_queue.pop_front()
    }

    // O(1) push to back
    pub fn enqueue_ready(&mut self, task_id: u32) -> bool {
        if self.ready_queue.len() >= 10000 {
            return false;
        }
        self.ready_queue.push_back(task_id);
        true
    }

    // O(1) add to suspended set
    pub fn enqueue_suspended(&mut self, task_id: u32) -> bool {
        self.suspended_map.insert(task_id)
    }

    // O(1) remove from suspended set
    pub fn dequeue_suspended(&mut self, task_id: u32) -> bool {
        self.suspended_map.remove(&task_id)
    }

    pub fn ready_count(&self) -> usize {
        self.ready_queue.len()
    }

    pub fn suspended_count(&self) -> usize {
        self.suspended_map.len()
    }
}

// Event loop with work-stealing
pub struct EventLoopPool {
    queue: Arc<OptimizedTaskQueue>,
    wakeup_ring: Arc<WakeupRing>,
    task_count: std::sync::atomic::AtomicUsize,
}

impl EventLoopPool {
    pub fn new() -> Self {
        Self {
            queue: Arc::new(OptimizedTaskQueue::new()),
            wakeup_ring: Arc::new(WakeupRing::new()),
            task_count: std::sync::atomic::AtomicUsize::new(0),
        }
    }

    // Work-stealing: Try to steal from wakeup events first
    pub fn poll_next(&mut self) -> Option<u32> {
        // Priority 1: Wakeup events (hot path)
        if let Some(event) = self.wakeup_ring.pop() {
            return Some(event.task_id);
        }

        // Priority 2: Ready queue
        self.queue.dequeue_ready()
    }

    // Batch emit wakeup events (for I/O completions)
    pub fn emit_batch(&self, events: &[WakeupEvent]) {
        for event in events {
            self.wakeup_ring.push(*event);
        }
    }

    pub fn task_count(&self) -> usize {
        self.task_count.load(std::sync::atomic::Ordering::Relaxed)
    }
